import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { t, text, titleOf } from '../util';
import { myLists, addToList } from '../api';
/** Put a title on one of your lists, or on a new one. */
export default class AddToListModal extends FormModal {
  lists = null;
  name = '';
  added = new Set();
  oninit(vnode) {
    super.oninit(vnode);
    myLists().then(lists => {
      this.lists = lists;
      m.redraw();
    });
  }
  className() {
    return 'ShelfAddModal Modal--small';
  }
  title() {
    return t('add.title', {
      title: m("em", null, titleOf(this.attrs.media))
    });
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, this.lists === null ? m(LoadingIndicator, null) : this.lists.length ? this.listButtons(this.lists) : null, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "shelf-new-list"
    }, t('add.new_list')), m("div", {
      className: "ShelfAddModal-new"
    }, m("input", {
      id: "shelf-new-list",
      className: "FormControl",
      maxlength: "100",
      placeholder: text('add.new_list_placeholder'),
      value: this.name,
      oninput: e => {
        this.name = e.target.value;
      }
    }), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading,
      disabled: !this.name.trim()
    }, t('add.create'))))));
  }
  listButtons(lists) {
    return m("ul", {
      className: "ShelfAddModal-lists"
    }, lists.map(list => m("li", null, m(Button, {
      className: "Button Button--block",
      icon: this.added.has(list.id()) ? 'fas fa-check' : 'fas fa-plus',
      disabled: this.added.has(list.id()) || this.loading,
      onclick: () => this.add(list)
    }, list.name(), " ", m("small", null, t('lists.items', {
      count: list.itemCount()
    }))))));
  }
  add(list) {
    this.loading = true;
    addToList(list, this.attrs.media).then(() => {
      this.loading = false;
      this.added.add(list.id());
      app.alerts.show({
        type: 'success'
      }, t('add.added', {
        list: list.name()
      }));
      m.redraw();
    }, this.loaded.bind(this));
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.name.trim()) return;
    this.loading = true;
    addToList(null, this.attrs.media, this.name.trim()).then(list => {
      app.alerts.show({
        type: 'success'
      }, t('add.added', {
        list: list.name()
      }));
      this.hide();
    }, this.loaded.bind(this));
  }
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/AddToListModal', AddToListModal);